/**
 * The Child
 * ----------
 * The Shunammite's son collapses in the field; she carries him to the room and lays him on Elisha's bed, and the prophet restores him. Stage: a field at midday, a child limp in his mother's arms, then the room with the boy breathing again; urgency, then quiet light.
 *
 * Palette 0x241810 → 0x060402 · light: dusk · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./elisha-kit.js.
 */

import { THREE, createScene, house, wheat, pillar, person } from './elisha-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 956026791, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 12, 0, -19, 1.0 + W.r() * 0.3, { mud: 0x060402 });

    /* fields: standing grain to the horizon */
    wheat(W, group, 0, 34, 220, 110, { h: 2.1, stalk: 0x281a12, head: 0x2d1e14 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x2f1f15, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, beard: 'long', staff: 'planted', ry: -0.21, s: 1.06 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, beard: 'long', staff: 'planted', ry: 0.28, s: 1.08 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, beard: 'long', staff: 'planted', ry: 0.45, s: 1.15 });

    return W.finish();
}

export default { build };
